<template><div class="pagination"><span>{{ from }}–{{ to }} / {{ total }}</span><div><button class="button secondary" type="button" :disabled="page <= 1" @click="emit('update:page', page-1)">Previous</button><button class="button secondary" type="button" :disabled="page >= pages" @click="emit('update:page', page+1)">Next</button></div></div></template>
<script setup lang="ts">import { computed } from 'vue'; const props=defineProps<{page:number;pageSize:number;total:number}>(); const emit=defineEmits<{ 'update:page':[value:number] }>(); const pages=computed(()=>Math.max(1,Math.ceil(props.total/props.pageSize))); const from=computed(()=>props.total?((props.page-1)*props.pageSize)+1:0); const to=computed(()=>Math.min(props.total,props.page*props.pageSize))</script>
